// Role IDs are resolved from the live guild rather than hand-maintained JSON, so the
// user types role NAMES and there is no snowflake left to typo or to go stale on rename.
const cfg = $('Set Reconcile Settings').first().json;
const guildRoles = $('Get Guild Roles').all().map(function (i) { return i.json; });

const byName = {};
for (const r of guildRoles) {
  if (r && r.id && r.name) { byName[String(r.name).trim().toLowerCase()] = String(r.id); }
}

const gatedNames = String(cfg.gated_roles || '')
  .split(',').map(function (s) { return s.trim(); }).filter(function (s) { return s.length > 0; });
const gatedByName = {};
const gatedMissing = [];
for (const name of gatedNames) {
  const id = byName[name.toLowerCase()];
  if (id) { gatedByName[name.toLowerCase()] = id; } else { gatedMissing.push(name); }
}

function csv(v) {
  return String(v || '').split(',').map(function (s) { return s.trim().toLowerCase(); })
    .filter(function (s) { return s.length > 0; });
}
const activeValues = csv(cfg.active_status_values);
const inactiveValues = csv(cfg.inactive_status_values);

const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  const userId = String(r.discord_user_id == null ? '' : r.discord_user_id).trim();
  const roleName = String(r.entitled_role == null ? '' : r.entitled_role).trim();
  const status = String(r.status == null ? '' : r.status).trim();
  const displayName = String(r.display_name == null ? '' : r.display_name).trim();

  if (userId === '' && roleName === '' && status === '' && displayName === '') { continue; }

  const idValid = /^[0-9]{17,20}$/.test(userId);
  const roleId = gatedByName[roleName.toLowerCase()] || '';

  let rosterActive = true;
  let problem = '';

  if (!idValid) {
    problem = userId.length === 0 ? 'discord_user_id is blank' : 'discord_user_id is not a Discord snowflake';
  } else if (roleId === '') {
    problem = 'entitled_role "' + roleName + '" is not one of gated_roles, or no role with that name exists in this server';
  } else if (status.length > 0) {
    const s = status.toLowerCase();
    if (activeValues.indexOf(s) >= 0) { rosterActive = true; }
    else if (inactiveValues.indexOf(s) >= 0) { rosterActive = false; }
    else {
      // Previously an unrecognised status was silently treated as inactive, which told
      // the coordinator to strip roles from members who were paid up.
      problem = 'status "' + status + '" matches neither active_status_values nor inactive_status_values, so this row cannot be judged';
    }
  }

  out.push({ json: {
    discord_user_id: userId,
    display_name: displayName,
    entitled_role: roleName,
    entitled_role_id: roleId,
    status: status,
    roster_active: rosterActive,
    usable: problem === '',
    problem: problem,
    roster_empty: false,
    gated_missing: gatedMissing
  } });
}

if (out.length === 0) {
  // A blank tab used to end the run silently, because n8n skips a node fed zero items.
  out.push({ json: {
    discord_user_id: '', display_name: '', entitled_role: '', entitled_role_id: '',
    status: '', roster_active: false, usable: false,
    problem: 'The roster tab returned no rows. Check roster_tab_name and that the tab has a header row plus data.',
    roster_empty: true, gated_missing: gatedMissing
  } });
}

return out;

const cfg = $('Set Reconcile Settings').first().json;
const roster = $('Normalize Roster Rows').all().map(function (i) { return i.json; });
const members = $input.all().map(function (i) { return i.json; });
const guildRoles = $('Get Guild Roles').all().map(function (i) { return i.json; });

const roleIdToName = {};
for (const r of guildRoles) {
  if (r && r.id && r.name) { roleIdToName[String(r.id)] = String(r.name); }
}
const gatedNames = String(cfg.gated_roles || '')
  .split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(function (s) { return s.length > 0; });
const gatedRoleIds = new Set();
for (const id of Object.keys(roleIdToName)) {
  if (gatedNames.indexOf(roleIdToName[id].toLowerCase()) >= 0) { gatedRoleIds.add(id); }
}

const ignored = new Set(String(cfg.ignore_user_ids || '')
  .split(',').map(function (s) { return s.trim(); }).filter(function (s) { return s.length > 0; }));

const graceDays = Number(cfg.grace_period_days);
const graceMs = (isFinite(graceDays) && graceDays > 0) ? graceDays * 86400000 : 0;
const nowMs = Date.now();

const checkedAt = $now.toISO();
const runId = String($execution.id);

const inServer = new Map();
for (const m of members) {
  const user = m.user || {};
  const uid = String(user.id || m.id || '').trim();
  if (uid.length === 0) continue;
  if (user.bot === true) continue;
  if (ignored.has(uid)) continue;
  const joinedMs = m.joined_at ? new Date(m.joined_at).getTime() : 0;
  inServer.set(uid, {
    id: uid,
    username: String(user.username || ''),
    roles: (Array.isArray(m.roles) ? m.roles : []).map(String),
    inGrace: graceMs > 0 && joinedMs > 0 && (nowMs - joinedMs) < graceMs
  });
}

const drift = [];
function makeRow(bucket, uid, displayName, username, role, note) {
  return { checked_at: checkedAt, run_id: runId, bucket: bucket, discord_user_id: uid,
           display_name: displayName, discord_username: username, role: role, note: note };
}

const rosterEmpty = roster.length === 1 && roster[0].roster_empty === true;
const gatedMissing = (roster[0] && Array.isArray(roster[0].gated_missing)) ? roster[0].gated_missing : [];
for (const name of gatedMissing) {
  drift.push(makeRow('gated_role_not_found', '', '', '', name,
    'gated_roles names a role that does not exist in this server. Check the spelling against Server Settings, Roles.'));
}

const rosterByUser = new Map();
const unusable = [];
if (!rosterEmpty) {
  for (const r of roster) {
    if (!r.usable) { unusable.push(r); continue; }
    const list = rosterByUser.get(r.discord_user_id) || [];
    list.push(r);
    rosterByUser.set(r.discord_user_id, list);
  }

  for (const pair of rosterByUser) {
    const uid = pair[0];
    const member = inServer.get(uid);
    for (const r of pair[1]) {
      if (!r.roster_active) continue;
      const holds = member ? member.roles.indexOf(r.entitled_role_id) >= 0 : false;
      if (holds) continue;
      if (member && member.inGrace) {
        drift.push(makeRow('in_grace_period', uid, r.display_name, member.username, r.entitled_role,
          'Joined within the last ' + graceDays + ' days and does not hold the role yet. Not counted as drift.'));
        continue;
      }
      drift.push(makeRow('missing_role', uid, r.display_name, member ? member.username : '', r.entitled_role,
        member ? 'In the server but does not hold the entitled role' : 'On the roster but not found in the server'));
    }
  }

  for (const pair of inServer) {
    const uid = pair[0];
    const member = pair[1];
    const held = member.roles.filter(function (rid) { return gatedRoleIds.has(rid); });
    if (held.length === 0) continue;
    const rows = rosterByUser.get(uid) || [];
    for (const rid of held) {
      const roleName = roleIdToName[rid];
      if (rows.length === 0) {
        drift.push(makeRow('no_roster_row', uid, '', member.username, roleName, 'Holds a gated role with no roster row at all'));
        continue;
      }
      const entitled = rows.some(function (r) { return r.roster_active && r.entitled_role_id === rid; });
      if (entitled) continue;
      const staleRow = rows.some(function (r) { return r.entitled_role_id === rid; });
      drift.push(makeRow('unexpected_role', uid, rows[0].display_name, member.username, roleName,
        staleRow ? 'Roster row for this role is not an active status' : 'Roster does not entitle this member to the role'));
    }
  }
}

for (const r of unusable) {
  drift.push(makeRow('roster_row_unusable', r.discord_user_id, r.display_name, '', r.entitled_role, r.problem));
}
if (rosterEmpty) {
  drift.push(makeRow('roster_empty', '', '', '', '', roster[0].problem));
}

const order = { gated_role_not_found: 0, roster_empty: 1, no_roster_row: 2, missing_role: 3,
                unexpected_role: 4, roster_row_unusable: 5, in_grace_period: 6 };
drift.sort(function (a, b) {
  return (order[a.bucket] - order[b.bucket]) ||
    String(a.display_name || a.discord_username).localeCompare(String(b.display_name || b.discord_username));
});

if (drift.length === 0) {
  drift.push(makeRow('no_drift', '', '', '', '',
    'Checked ' + inServer.size + ' members against ' + rosterByUser.size + ' rostered users and found no drift'));
}

// Counts travel with the rows so the channel post and the sheet can never disagree.
const summary = { members_scanned: inServer.size, roster_users: rosterByUser.size,
                  roster_rows: rosterEmpty ? 0 : roster.length };
return drift.map(function (d) { return { json: Object.assign({}, d, { __summary: summary }) }; });

const cfg = $('Set Reconcile Settings').first().json;
const rows = $('Reconcile Roster Against Discord').all().map(function (i) { return i.json; });

// Counts come from the reconcile step, so the channel post and the sheet cannot disagree.
const s = (rows[0] && rows[0].__summary) || { members_scanned: 0, roster_users: 0, roster_rows: 0 };

const maxExamples = Number(cfg.max_examples_in_summary || 5);
function pick(bucket) { return rows.filter(function (r) { return r.bucket === bucket; }); }

const noRosterRow = pick('no_roster_row');
const missingRole = pick('missing_role');
const unexpectedRole = pick('unexpected_role');
const unusableRows = pick('roster_row_unusable');
const inGrace = pick('in_grace_period');
const roleNotFound = pick('gated_role_not_found');
const rosterEmpty = pick('roster_empty');
const notInServer = missingRole.filter(function (r) { return String(r.note).indexOf('not found in the server') !== -1; });

function label(r) { return (r.display_name || r.discord_username || r.discord_user_id) + ' (' + r.role + ')'; }
function examples(list) {
  const shown = list.slice(0, maxExamples).map(label).join(', ');
  return list.length > maxExamples ? shown + ', plus ' + (list.length - maxExamples) + ' more' : shown;
}

const lines = [];
lines.push('**Roster drift report, ' + $now.toFormat('d LLLL yyyy') + '**');
lines.push('');

if (roleNotFound.length > 0) {
  lines.push('**Configuration problem.** ' + roleNotFound.length + ' name(s) in gated_roles do not exist in this server: ' +
             roleNotFound.map(function (r) { return r.role; }).join(', ') + '. Counts below ignore those roles.');
  lines.push('');
}
if (rosterEmpty.length > 0) {
  lines.push('**The roster tab returned no rows.** Nothing could be reconciled. Check roster_tab_name.');
  lines.push('');
} else {
  lines.push('**' + noRosterRow.length + '** members hold a gated role with no roster row.');
  lines.push('**' + missingRole.length + '** roster members are missing their entitled role.');
  lines.push('');
  if (noRosterRow.length > 0) lines.push('No roster row: ' + examples(noRosterRow));
  if (missingRole.length > 0) lines.push('Missing role: ' + examples(missingRole));
  if (notInServer.length > 0) lines.push('Of those missing a role, ' + notInServer.length + ' are no longer in the server at all.');
  if (unexpectedRole.length > 0) lines.push('Holding a role the roster does not grant: ' + unexpectedRole.length + '. ' + examples(unexpectedRole));
  if (inGrace.length > 0) lines.push(inGrace.length + ' recent joiner(s) are inside the ' + cfg.grace_period_days + ' day grace period and were not counted.');
  if (unusableRows.length > 0) lines.push('**' + unusableRows.length + ' roster row(s) could not be judged** and are excluded from every count above. Fix them before trusting these numbers: ' + examples(unusableRows));
  if (rows.length === 1 && rows[0].bucket === 'no_drift') lines.push('No drift found this week.');
}

lines.push('');
lines.push('Scanned ' + s.members_scanned + ' Discord members (bots and ignored IDs excluded) against ' +
           s.roster_users + ' rostered users from ' + s.roster_rows + ' roster rows. Row level detail is on the ' +
           (cfg.report_tab_name || 'drift report') + ' tab. This workflow only reads Discord, it never adds or removes a role.');

let content = lines.join('\n');
if (content.length > 1900) content = content.slice(0, 1880) + '\n(truncated, see the sheet)';

return [{ json: {
  content: content,
  no_roster_row_count: noRosterRow.length,
  missing_role_count: missingRole.length,
  unexpected_role_count: unexpectedRole.length,
  unusable_row_count: unusableRows.length,
  in_grace_count: inGrace.length,
  role_not_found_count: roleNotFound.length,
  members_scanned: s.members_scanned,
  roster_users: s.roster_users,
  roster_rows: s.roster_rows
} }];
